import sys

def find_squares(n):
    if n % 2 == 0:
        return "impossible"

    for k in range(1, int(n**0.5) + 1):
        if (n + k * k) % 2 == 0:
            m_squared = (n + k * k) // 2
            m = int(m_squared**0.5)
            if m * m == m_squared:
                return f"{m} {k}"

    return "impossible"

if __name__ == "__main__":
    n = int(sys.stdin.read().strip())
    result = find_squares(n)
    print(result)

import sys

def find_dimensions(n):
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            j = n // i
            if (i + j) % 2 == 0 and (j - i) % 2 == 0:
                m = (i + j) // 2
                k = (j - i) // 2
                return m, k
    return "impossible"

if __name__ == "__main__":
    n = int(sys.stdin.read().strip())
    result = find_dimensions(n)
    print(result)

def find_dimensions(n):
    for i in range(1, int(n**0.5) + 1):
        if (n + i * i) % (2 * i) == 0:
            j = (n + i * i) // (2 * i)
            return (i + j, j - i)
    return "impossible"

